import type { RequestEventBase } from "@builder.io/qwik-city";

/**
 * Cloudflare bindings (DB, MEDIA_BUCKET, ASSETS, ...) for the current request.
 *
 * `requestEvent.platform` is typed as `PlatformVercel` (`{}`) at the ambient
 * `QwikCityPlatform` level, because entry.vercel-edge.tsx still declares that
 * global for the Vercel deployment. This casts to the real shape used when
 * running on Cloudflare (see worker-configuration.d.ts, generated by
 * `wrangler types` from wrangler.jsonc) — safe because the only callers of
 * this helper are routes that only ever run on the Cloudflare deployment.
 */
export function getOptionalEnv(requestEvent: RequestEventBase): Env | undefined {
  return (requestEvent.platform as unknown as { env?: Env } | undefined)?.env;
}

export function getEnv(requestEvent: RequestEventBase): Env {
  const env = getOptionalEnv(requestEvent);
  if (!env) {
    throw new Error("Cloudflare environment is unavailable for this request");
  }
  return env;
}
